━━━━━━━━━━━━━━━━━━━━━━
【図解】吸収冷凍機の4つの器
　蒸発器：冷媒（水）が真空中で蒸発し冷水を冷やす★
　吸収器：水蒸気を吸収液（臭化リチウム）が吸い込む
　再生器：加熱して吸収液から水分を追い出す（熱源投入）
