　工種別施工計画書：配管・ダクト等の詳細な施工要領
　施工図（製作図・総合図）：実寸法・他業種との取合い
　施工要領書：作業手順・使用材料・品質確認方法
　工程表：バーチャート・ネットワーク工程表

・材料・機器は搬入前に承認（承諾）を受ける
・官公庁への届出（消防・労基署等）は着工前後の期限を守る

━━━━━━━━━━━━━━━━━━━━━━
