        body: `▼ゼロから
　工事は材料を「必要な量だけ・むだなく」用意することから始まる。
　量を見積もる作業が積算。そして現場で最も多い事故が「高い所
　からの墜落」「電気による感電」「暑さによる熱中症」。これらは
　防ぎ方が確立しているので、対策をセットで覚えるのが得点源。

━━━━━━━━━━━━━━━━━━━━━━
🔑 材料・数量と積算
━━━━━━━━━━━━━━━━━━━━━━
【図解】積算の考え方
　設計図・仕様書 → 数量拾い（配管長・継手・機器）
　　→ 材料費＋労務費＋機械経費＝直接工事費
　　→ ＋共通仮設費・現場管理費・一般管理費＝工事費★
　ロス率（切りしろ・端材）を見込んで所要量を算出★

・配管は口径・材質ごとに延べ長さを拾い、継手・弁を数える
・保温・塗装は面積・長さで拾う
・歩掛り（標準的な作業量の目安）で労務工数を見積もる

━━━━━━━━━━━━━━━━━━━━━━
🔑 墜落・転落の防止
━━━━━━━━━━━━━━━━━━━━━━
【図解】墜落防止の基本
　高さ2m以上：作業床・手すり（85cm以上）・墜落制止用器具★
　作業床：幅40cm以上・すき間3cm以下・幅木10cm以上★
　開口部・端部：手すり・囲い・覆い・表示
　→ 墜落制止用器具は原則フルハーネス型を使用★

・脚立・可搬式作業台：天板に立たない・またがない
・移動はしご：上端を60cm以上突出・すべり止め・要所を固定
・悪天候（強風・大雨・大雪）時は高所作業を中止する★

━━━━━━━━━━━━━━━━━━━━━━
🔑 感電・電気災害の防止
━━━━━━━━━━━━━━━━━━━━━━
【図解】感電防止の要点
　○停電作業：検電→短絡接地→施錠・表示（活線の思い込み防止）★
　○活線近接作業：絶縁用保護具・防具・囲いを使用
　○漏電遮断器・接地（アース）で感電・火災を防ぐ★
　×濡れた手・濡れた場所での電気機器の取扱い

・仮設電気：配線の損傷・タコ足配線を避ける・定期点検
・アーク溶接：感電・アーク光・ヒュームに注意（保護具着用）

━━━━━━━━━━━━━━━━━━━━━━
🔑 熱中症・その他の健康障害の防止
━━━━━━━━━━━━━━━━━━━━━━
【図解】熱中症予防（WBGT）
　暑さ指数WBGT：気温・湿度・輻射を総合した指標★
　　→ 値が高いほど危険・こまめな水分と塩分の補給★
　　→ 作業と休憩のサイクル・涼しい休憩場所の確保
　通気性のよい服装・帽子・送風・スポットクーラー

・粉じん作業：防じんマスク・局所排気（じん肺予防）
・有機溶剤・特定化学物質：換気・保護具・作業主任者
・振動工具：手腕振動障害の予防（連続使用時間の管理）

⚠ ひっかけ注意
・「墜落制止用器具は胴ベルト型が原則」→ ×（原則フルハーネス型）
・「作業床の幅木は不要」→ ×（10cm以上・落下物防止）
・「停電作業で検電だけすればよい」→ ×（短絡接地・施錠表示も）
・「WBGTは気温だけの指標」→ ×（湿度・輻射も含む総合指標）

★ここだけ暗記
・工事費＝直接費＋共通仮設＋現場管理＋一般管理／ロス率考慮
・2m/作業床40cm・手すり85cm・幅木10cm・フルハーネス
・停電作業＝検電・短絡接地・施錠表示／漏電遮断器＋接地
・熱中症はWBGTで管理・水分塩分・休憩`,
