　移動式クレーン運転士免許：つり上げ荷重5t以上★
　小型移動式クレーン運転技能講習：1t以上5t未満★
　特別教育：つり上げ荷重1t未満★
　玉掛け：1t以上＝技能講習／1t未満＝特別教育★

・クレーンは定格荷重を超える荷をつってはならない
・強風（10分間平均風速10m/s以上等）時は作業中止★
・合図は指名された合図者が統一した方法で行う

